parameters.dateTime:
={{ 
  (() => {
    const submitted = new Date($json.submittedAt);
    let next = new Date(submitted);
    next.setDate(submitted.getDate() + 1);

    // Skip weekends
    while ([0, 6].includes(next.getDay())) {
      next.setDate(next.getDate() + 1);
    }

    // Set to 2 PM local time (UTC-5)
    next.setUTCHours(19, 0, 0, 0); // 14:00 local = 19:00 UTC

    // Format as local-time style (without timezone)
    const local = new Date(next.getTime() - 5 * 60 * 60 * 1000); // shift back 5h
    return local.toISOString().split('.')[0];
  })()
}}

